# fix-email-reporter-v3.ps1
Set-StrictMode -Off
$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'Create_Package.test.js')) {
    Write-Host 'ERROR: Run from Commercial Line Performance test folder' -ForegroundColor Red; exit 1
}

Write-Host 'Writing emailReporter.js (per-state files, no race condition)...' -ForegroundColor Yellow
$b64 = ''
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path $PWD 'emailReporter.js'), $bytes)

node -c emailReporter.js
if ($LASTEXITCODE -eq 0) { Write-Host 'Syntax check PASSED' -ForegroundColor Green }
else { Write-Host 'Syntax check FAILED' -ForegroundColor Red; exit 1 }

git add emailReporter.js
git commit -m "Fix: per-state iteration files eliminate parallel write race condition, merged at email time"
git push origin main

if ($LASTEXITCODE -eq 0) {
    Write-Host ''
    Write-Host 'Pushed.' -ForegroundColor Green
    Write-Host 'Each state now writes to iterations-data-package-DE.json etc.'
    Write-Host 'Runner merges all 4 into consolidated email.'
} else {
    Write-Host 'Push failed' -ForegroundColor Red
}
